import{_ as t,a as r}from"./chunks/ugso_trigger_value.B1HIiOLA.js";import{_ as n,a as i,b as a,c as s,d,e as o,f as l,g,h,i as u,j as c,k as m,l as p,m as b,n as x,o as _,p as f,q as k,r as w,s as A,t as z,u as y,v,w as B,x as S,y as T,z as H,A as E,B as Z,C as j,D,E as O,F as L,G as N,H as J,I as F,J as W,K as I,L as V,M as q,N as U,O as M,P,Q as G,R as K,S as R,T as C,U as Y,V as Q,W as $,X,Y as ee,Z as te,$ as re,a0 as ne,a1 as ie,a2 as ae,a3 as se,a4 as de,a5 as oe,a6 as le,a7 as ge,a8 as he,a9 as ue,aa as ce,ab as me,ac as pe,ad as be,ae as xe,af as _e,ag as fe,ah as ke,ai as we,aj as Ae,ak as ze,al as ye,am as ve,an as Be,ao as Se,ap as Te,aq as He,ar as Ee,as as Ze,at as je,au as De,av as Oe,aw as Le,ax as Ne,ay as Je,az as Fe,aA as We,aB as Ie,aC as Ve,aD as qe,aE as Ue,aF as Me,aG as Pe,aH as Ge,aI as Ke,aJ as Re,aK as Ce,aL as Ye,aM as Qe,aN as $e,aO as Xe,aP as et,aQ as tt,aR as rt,aS as nt,aT as it,aU as at,aV as st,aW as dt,aX as ot,aY as lt,aZ as gt,a_ as ht,a$ as ut,b0 as ct,b1 as mt,b2 as pt,b3 as bt,b4 as xt,b5 as _t,b6 as ft,b7 as kt,b8 as wt,b9 as At,ba as zt,bb as yt,bc as vt,bd as Bt,be as St,bf as Tt,bg as Ht,bh as Et,bi as Zt,bj as jt,bk as Dt,bl as Ot,bm as Lt,bn as Nt,bo as Jt,bp as Ft,bq as Wt,br as It,bs as Vt,bt as qt,bu as Ut,bv as Mt,bw as Pt,bx as Gt,by as Kt,bz as Rt,bA as Ct,bB as Yt,bC as Qt,bD as $t,bE as Xt,bF as er,bG as tr,bH as rr,bI as nr}from"./chunks/ugso_jinja_for.CdntdN2C.js";import{_ as ir,a as ar}from"./chunks/ugso_whatsapp_action.CCiayXGK.js";import{_ as sr}from"./chunks/ugso_callmebot_signal_action.khNgQHDV.js";import{_ as dr,a as or}from"./chunks/ugso_template_condition.B_NKCd7q.js";import{_ as lr,a as gr,b as hr}from"./chunks/ugso_jinja_composed_value.CRlFxrSw.js";import{_ as ur,o as cr,c as mr,a3 as pr}from"./chunks/framework.BlfGB29P.js";const Er=JSON.parse('{"title":"Liste der Blocks","description":"Alle UGSo Blocks für HA mit Bild, Funktion und Originalplugins.","frontmatter":{"title":"Liste der Blocks","description":"Alle UGSo Blocks für HA mit Bild, Funktion und Originalplugins."},"headers":[],"relativePath":"projects/blocks-for-ha/blocks.md","filePath":"projects/blocks-for-ha/blocks.md","lastUpdated":1793126212000}'),br={name:"projects/blocks-for-ha/blocks.md"};function xr(_r,e,fr,kr,wr,Ar){return cr(),mr("div",null,[...e[0]||(e[0]=[pr('<h1 id="liste-der-blocks" tabindex="-1">Liste der Blocks <a class="header-anchor" href="#liste-der-blocks" aria-label="Permalink to &quot;Liste der Blocks&quot;">​</a></h1><p>Seit <strong>0.1.66</strong> starten einfache Textwerte kategorienweit leer: MQTT-Topic und Nachricht, Objekt-/Listeninhalte, Umwandlungen und Ersatzwerte enthalten keine Beispieltexte. Assist-Antwort und Jinja-Text verwenden ebenfalls einzeilige Textfelder. Erforderliche Inhalte vor dem Export selbst eintragen. Trennzeichen, gültige JSON-Grundstrukturen sowie Zahlen-, Zeit- und Aktionseinstellungen bleiben erhalten. Gespeicherte Texte werden beim Öffnen nicht geleert, auch vorhandene Zeilenumbrüche bleiben erhalten. Mehrzeilige Jinja-Code- und JSON-Editoren bleiben verfügbar.</p><h2 id="einzelne-logikblocke-und-ha-zahnrader-seit-0-1-61" tabindex="-1">Einzelne Logikblöcke und HA-Zahnräder seit 0.1.61 <a class="header-anchor" href="#einzelne-logikblocke-und-ha-zahnrader-seit-0-1-61" aria-label="Permalink to &quot;Einzelne Logikblöcke und HA-Zahnräder seit 0.1.61&quot;">​</a></h2><p><strong>und</strong> (<code>ugso_and</code>) und <strong>oder</strong> (<code>ugso_or</code>) sind eigene erweiterbare Blöcke; <strong>nicht</strong> bleibt ein einzelner Eingang. Der kombinierte <code>ugso_logic_condition</code> ist nur für alte Projekte unterstützt. Optionale HA-Eingaben lassen sich im Zahnrad einzeln hinzufügen, entfernen und anordnen. <a href="./advanced">Vollständige Gegenüberstellung der geprüften Blockgruppen und Bilder</a>.</p><h2 id="zeitplan-und-ausloserdaten-seit-0-1-60" tabindex="-1">Zeitplan und Auslöserdaten seit 0.1.60 <a class="header-anchor" href="#zeitplan-und-ausloserdaten-seit-0-1-60" aria-label="Permalink to &quot;Zeitplan und Auslöserdaten seit 0.1.60&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Baustein</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Zeitplan</strong> · Auslöser<br><code>ugso_schedule_trigger</code></td><td><img src="'+t+'" alt="Zeitplan" style="max-width:280px;max-height:180px;"></td><td>CRON-Feld mit Wizard/Einfach/CRON-Dialog und Sekunden. Native HA-Zeitmuster und Uhrzeiten mit Wochentagen. <a href="./time">Unterstützte Regeln und Grenzen</a>.</td></tr><tr><td><strong>↪ Auslöserdaten</strong> · Auslöser<br><code>ugso_trigger_value</code></td><td><img src="'+r+'" alt="Auslöserdaten" style="max-width:280px;max-height:180px;"></td><td>Wert/alter Wert, Entitäts-ID, Auslöser-ID/-typ, MQTT-Meldung/JSON und Ereignisdaten. Fehlende Daten: <code>none</code>.</td></tr></tbody></table><p>Erweiterte native HA-Auslöser sind direkt unter <strong>Auslöser</strong> einsortiert. Der Sonnenauslöser hat zusätzlich einen optionalen Minutenversatz. <a href="./time">Gegenüberstellung der ioBroker-Trigger</a>.</p><h2 id="beschriftungen-kommentar-und-mqtt-seit-0-1-59" tabindex="-1">Beschriftungen, Kommentar und MQTT seit 0.1.59 <a class="header-anchor" href="#beschriftungen-kommentar-und-mqtt-seit-0-1-59" aria-label="Permalink to &quot;Beschriftungen, Kommentar und MQTT seit 0.1.59&quot;">​</a></h2><p>Standardbeschriftungen und Zahnrad-Popups folgen jetzt ioBroker/Blockly in DE/EN/FR: <strong>Attribute / Attribut</strong>, <strong>Liste / Element</strong>, <strong>verbinden / Element</strong> und <strong>der Fall ist / im Falle von / default</strong>. Attributnamen sind im Popup editierbar; der default-Zweig ist hinzufügbar und entfernbar. Text-, Listen-, Mathematik- und Logikbeschriftungen wurden angeglichen. Zusätzliche HA-Eingaben, unveränderliche Variablenzuweisungen, Python-Datumsformate und die nächste Sonnenzeit bleiben ausdrücklich erkennbar.</p><table tabindex="0"><thead><tr><th>Baustein</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Kommentar</strong> · System<br><code>ugso_comment</code></td><td><img src="'+n+'" alt="Kommentar" style="max-width:280px;max-height:180px;"></td><td>Gelbe Notiz, frei oder in einer Aktionskette. Projekt-JSON erhält Text und Position. Aktive Kommentare werden im YAML als <code>#</code>-Zeilen vor der Automation gesammelt und beim Import wieder als freie Kommentarblöcke übernommen, auch beim Ergänzen. Ursprüngliche YAML-Kommentarpositionen werden nicht bewahrt. Keine Aktion.</td></tr><tr><td><strong>MQTT-Nachricht</strong> · Nachrichten<br><code>ugso_mqtt_action</code></td><td><img src="'+i+'" alt="MQTT-Nachricht" style="max-width:280px;max-height:180px;"></td><td>Thema (Topic), Nachricht, Retain und QoS 0/1/2. Text- oder Jinja-Eingänge; native Ausgabe <code>mqtt.publish</code>. Keine Instanzauswahl. Die MQTT-Integration von HA muss eingerichtet sein; HA führt das Senden aus.</td></tr></tbody></table><p>Seit <strong>0.1.58</strong> orientiert sich die Bedienung möglichst eng an ioBroker: Erweiterungen ausschließlich über das Zahnrad, ohne zusätzliche +/−/S-Knöpfe. Dies gilt auch für Objekte, Listen, Text, Fallauswahl und Parallel. Der kompakte UND-/ODER-Block ist aus dem Menü entfernt; alte Projekte bleiben lesbar. HA-Felder, Verbindungen und YAML-Funktionen bleiben erhalten. Ziel ist vertraute ioBroker-Optik bei umfassender HA-Automationsunterstützung.</p><h2 id="nachrichten-seit-0-1-48" tabindex="-1">Nachrichten seit 0.1.48 <a class="header-anchor" href="#nachrichten-seit-0-1-48" aria-label="Permalink to &quot;Nachrichten seit 0.1.48&quot;">​</a></h2><p>Neue Kategorie <strong>Nachrichten</strong>, drei DE/EN/FR-Bausteine. <a href="./../callmebot/">Einrichtung, Schlüsselverwaltung und Versand</a>.</p><p>Seit <strong>0.1.50</strong> zusätzlich <strong>Signal · CallMeBot</strong> mit eigener Profilauswahl. <a href="./../callmebot-signal/">Signal-App einrichten</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>WhatsApp · CallMeBot</strong><br><code>ugso_callmebot_action</code></td><td><img src="'+ir+'" alt="CallMeBot" style="max-width:360px;max-height:180px;"></td><td>Empfängerprofil, Text/Jinja und Protokollstufe. MQTT-Versand über die CallMeBot Whatsapp-App. Schlüssel bleiben im Backend.</td></tr><tr><td><strong>Signal · CallMeBot</strong><br><code>ugso_callmebot_signal_action</code></td><td><img src="'+sr+'" alt="CallMeBot" style="max-width:360px;max-height:180px;"></td><td>Empfängerprofil, Text/Jinja und Protokollstufe. MQTT-Versand über die CallMeBot Signal-App. Schlüssel bleiben im Backend.</td></tr><tr><td><strong>WhatsApp-Integration</strong><br><code>ugso_whatsapp_action</code></td><td><img src="'+ar+'" alt="WhatsApp-Integration" style="max-width:360px;max-height:180px;"></td><td>whatsapp.send_message mit number oder target sowie notify.whatsapp. Empfänger ohne +, Nachricht, optionales Konto. Token einmal in der HA-Integration einrichten.</td></tr></tbody></table><h2 id="funktionen-seit-0-1-47" tabindex="-1">Funktionen seit 0.1.47 <a class="header-anchor" href="#funktionen-seit-0-1-47" aria-label="Permalink to &quot;Funktionen seit 0.1.47&quot;">​</a></h2><p>Der aktuelle Katalog enthält <strong>169 Blocktypen</strong>. <a href="./blockly-audit">Parameter, Export und Grenzen</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Aktionsfunktion definieren</strong><br><code>procedures_defnoreturn</code></td><td><img src="'+a+'" alt="Aktionsfunktion definieren" style="max-width:280px;max-height:180px;"></td><td>Wiederverwendbarer HA-Ablauf; bis zu acht Parameter über das Zahnrad. Definition neben der Automation.</td></tr><tr><td><strong>Aktionsfunktion aufrufen</strong><br><code>procedures_callnoreturn</code></td><td><img src="'+s+'" alt="Aktionsfunktion aufrufen" style="max-width:280px;max-height:180px;"></td><td>Dynamischer Aufruf mit Argumenteingängen. Export als HA-Ablaufgruppe mit eigenen Parameterbindungen.</td></tr><tr><td><strong>Bedingter Rückgabewert</strong><br><code>ugso_function_result</code></td><td><img src="'+d+'" alt="Falls gib zurück sonst" style="max-width:280px;max-height:180px;"></td><td>Falls / Wert / Sonst; nur der ausgewählte Wert wird in HA ausgewertet. Keine Aktionsfolge.</td></tr></tbody></table><p>Seit <strong>0.1.45</strong> enthält die Toolbox keine doppelten Einträge mehr: Zahl unter <strong>Mathematik</strong>, Text unter <strong>Text</strong>, Farbe unter <strong>Farbe</strong> und erweiterbares UND/ODER/NICHT unter <strong>Logik</strong>. <strong>Werte</strong> enthält nur Prozent. Die 163 Blocktypen und bestehende Projekte bleiben erhalten.</p><p>Entitätsfelder öffnen seit 0.1.17 einen Suchdialog. <a href="./entities">Entitäten laden, auswählen und manuell eingeben</a>.</p><p>Stand <strong>0.1.44</strong>: 163 Blocktypen. Alle Blocktypen wurden auf passende HA-Auswahlfelder geprüft. Die Bilder zeigen die tatsächlichen UGSo-Blocks im Editor. Dropdown-Varianten zählen nicht als zusätzliche Blocktypen. Anleitungen: <a href="./entities">HA-Auswahl</a>, <a href="./time">Datum und Zeit</a>, <a href="./conversion">Konvertierung</a>.</p><p>In Standard/Dark sind Auslöser orange, Bedingungen und Logik blau, Werte grün, Aktionen türkisblau und Objekte braun. Seitliche Anschlüsse sind typisiert; Auslöser und Aktionen bilden getrennte vertikale Ketten. Entitäts-IDs werden gesucht oder manuell eingegeben.</p><h2 id="farben-und-wertfunktionen-seit-0-1-15" tabindex="-1">Farben und Wertfunktionen seit 0.1.15 <a class="header-anchor" href="#farben-und-wertfunktionen-seit-0-1-15" aria-label="Permalink to &quot;Farben und Wertfunktionen seit 0.1.15&quot;">​</a></h2><p><a href="./blockly-audit">Bedienung, HA-Ausgabe und vollständiger Quellenvergleich</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Zufällige Farbe</strong><br><code>ugso_colour_random</code></td><td><img src="'+o+'" alt="Zufällige Farbe" style="max-width:280px;max-height:180px;"></td><td>Drei zufällige RGB-Kanäle 0–255. Bei jeder Auswertung neu; nicht kryptografisch.</td></tr><tr><td><strong>Farbe aus RGB</strong><br><code>ugso_colour_rgb</code></td><td><img src="'+l+'" alt="Farbe aus RGB" style="max-width:280px;max-height:180px;"></td><td>Prozentanteile auf 0–100 begrenzen und in RGB-Kanäle umrechnen. 100/50/0 ergibt [255,128,0].</td></tr><tr><td><strong>Farben mischen</strong><br><code>ugso_colour_blend</code></td><td><img src="'+g+'" alt="Farben mischen" style="max-width:280px;max-height:180px;"></td><td>Lineare RGB-Mischung. Anteil Farbe 2 von 0–1. Rot/Blau bei 0,5 ergibt [128,0,128], ohne Gamma-Korrektur.</td></tr><tr><td><strong>Wertfunktion definieren</strong><br><code>procedures_defreturn</code></td><td><img src="'+h+'" alt="Wertfunktion definieren" style="max-width:280px;max-height:180px;"></td><td>Originaler Blockly-Editor, Zahnrad für bis zu acht Parameter, Rückgabewert erforderlich. Keine Aktionen. Jinja-Expansion beim Export.</td></tr><tr><td><strong>Wertfunktion aufrufen</strong><br><code>procedures_callreturn</code></td><td><img src="'+u+'" alt="Wertfunktion aufrufen" style="max-width:280px;max-height:180px;"></td><td>Erscheint dynamisch in Funktionen. Argumenteingänge folgen den Parametern. Ergebnis als Wert oder Boolean-Bedingung; keine Rekursion.</td></tr><tr><td><strong>Originaler Parameter-Getter</strong><br><code>variables_get</code></td><td><img src="'+c+'" alt="Originaler Parameter-Getter" style="max-width:280px;max-height:180px;"></td><td>Original-Blockly-Getter, etwa aus dem Kontextmenü der Definition. Liest im Funktionskörper den Parameter, sonst eine HA-Variable. Eigener Getter bleibt nutzbar.</td></tr></tbody></table><h2 id="mathematik-text-listen-und-zahlschleifen-seit-0-1-14" tabindex="-1">Mathematik, Text, Listen und Zählschleifen seit 0.1.14 <a class="header-anchor" href="#mathematik-text-listen-und-zahlschleifen-seit-0-1-14" aria-label="Permalink to &quot;Mathematik, Text, Listen und Zählschleifen seit 0.1.14&quot;">​</a></h2><p><a href="./collections">Original-Blockly / ioBroker / HA: Zuordnung, Beispiele und Grenzen</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Arithmetik</strong><br><code>ugso_math_arithmetic</code></td><td><img src="'+m+'" alt="Arithmetik" style="max-width:280px;max-height:180px;"></td><td>Rechnet mit Zahlen: Addition, Subtraktion, Multiplikation, Division oder Potenz. Keine automatische Text-/Boolean-Konvertierung.</td></tr><tr><td><strong>Einzelne Zahl berechnen</strong><br><code>ugso_math_single</code></td><td><img src="'+p+'" alt="Einzelne Zahl berechnen" style="max-width:280px;max-height:180px;"></td><td>Wurzel, Betrag, Negation, Logarithmen und Exponentialfunktionen. Ungültige Werte erzeugen einen Templatefehler.</td></tr><tr><td><strong>Trigonometrie</strong><br><code>ugso_math_trig</code></td><td><img src="'+b+'" alt="Trigonometrie" style="max-width:280px;max-height:180px;"></td><td>Winkelfunktionen in Grad; inverse Funktionen liefern Grad. HA verwendet intern Radiant.</td></tr><tr><td><strong>Konstanten</strong><br><code>ugso_math_constant</code></td><td><img src="'+x+'" alt="Konstanten" style="max-width:280px;max-height:180px;"></td><td>Endliche mathematische Konstanten. Unendlich wird nicht als exportierbarer Zahlenwert angeboten.</td></tr><tr><td><strong>Zahleneigenschaften</strong><br><code>ugso_math_property</code></td><td><img src="'+_+'" alt="Zahleneigenschaften" style="max-width:280px;max-height:180px;"></td><td>Zahleneigenschaften prüfen. Teiler erscheint nur bei teilbar durch; Nullteiler ist ungültig.</td></tr><tr><td><strong>Runden</strong><br><code>ugso_math_round</code></td><td><img src="'+f+'" alt="Runden" style="max-width:280px;max-height:180px;"></td><td>Rundet auf 0–10 Nachkommastellen. HA/Jinja rundet halbe Werte zur geraden Zahl; Auf-/Abrunden folgen ceil/floor.</td></tr><tr><td><strong>Mathematik über Liste</strong><br><code>ugso_math_list</code></td><td><img src="'+k+'" alt="Mathematik über Liste" style="max-width:280px;max-height:180px;"></td><td>Statistik über eine Zahlenliste; Zufallseintrag akzeptiert beliebige Listenelemente. Leere Summe ist 0, andere leere Ergebnisse sind null.</td></tr><tr><td><strong>Modulo</strong><br><code>ugso_math_modulo</code></td><td><img src="'+w+'" alt="Modulo" style="max-width:280px;max-height:180px;"></td><td>Jinja-Modulo. Bei negativem Dividend folgt das Vorzeichen dem Teiler und kann von JavaScript abweichen.</td></tr><tr><td><strong>Begrenzen</strong><br><code>ugso_math_clamp</code></td><td><img src="'+A+'" alt="Begrenzen" style="max-width:280px;max-height:180px;"></td><td>Begrenzt einen Zahlenwert. Vertauschte Grenzen werden zuerst sortiert.</td></tr><tr><td><strong>Ganzzahlige Zufallszahl</strong><br><code>ugso_math_random_int</code></td><td><img src="'+z+'" alt="Ganzzahlige Zufallszahl" style="max-width:280px;max-height:180px;"></td><td>Inklusive beider ganzzahliger Grenzen. Höchstens 10000 mögliche Werte, vertauschte Grenzen sind erlaubt.</td></tr><tr><td><strong>Zufallsbruch</strong><br><code>ugso_math_random_fraction</code></td><td><img src="'+y+'" alt="Zufallsbruch" style="max-width:280px;max-height:180px;"></td><td>Zufallswert in Schritten von 0,00001. Kein kryptografischer Zufall; bei jeder Auswertung neu.</td></tr><tr><td><strong>Winkel atan2</strong><br><code>ugso_math_atan2</code></td><td><img src="'+v+'" alt="Winkel atan2" style="max-width:280px;max-height:180px;"></td><td>Vierquadranten-Winkelfunktion aus dem Blockly-Standard, zusätzlich zu den gezeigten Bildern.</td></tr><tr><td><strong>Zeilenumbruch</strong><br><code>ugso_text_newline</code></td><td><img src="'+B+'" alt="Zeilenumbruch" style="max-width:280px;max-height:180px;"></td><td>Liefert einen echten Zeilenumbruch für Textverknüpfung.</td></tr><tr><td><strong>Text verknüpfen</strong><br><code>ugso_text_join</code></td><td><img src="'+S+'" alt="Text verknüpfen" style="max-width:280px;max-height:180px;"></td><td>Verknüpft 0–100 Werte als Text. Zahnrad ändern die Anzahl der Eingänge.</td></tr><tr><td><strong>Text anhängen</strong><br><code>ugso_text_append</code></td><td><img src="'+T+'" alt="Text anhängen" style="max-width:280px;max-height:180px;"></td><td>Weist der vorher initialisierten Textvariable einen neuen Text zu. Kein Schreiben einer HA-Entität.</td></tr><tr><td><strong>Textlänge</strong><br><code>ugso_text_length</code></td><td><img src="'+H+'" alt="Textlänge" style="max-width:280px;max-height:180px;"></td><td>Anzahl Unicode-Codepunkte, nicht JavaScript-UTF-16-Codeeinheiten.</td></tr><tr><td><strong>Text ist leer</strong><br><code>ugso_text_empty</code></td><td><img src="'+E+'" alt="Text ist leer" style="max-width:280px;max-height:180px;"></td><td>Prüft einen Text auf Länge 0.</td></tr><tr><td><strong>Text enthält</strong><br><code>ugso_text_contains</code></td><td><img src="'+Z+'" alt="Text enthält" style="max-width:280px;max-height:180px;"></td><td>Prüft Teiltext, mit Groß-/Kleinschreibung.</td></tr><tr><td><strong>Text suchen</strong><br><code>ugso_text_index</code></td><td><img src="'+j+'" alt="Text suchen" style="max-width:280px;max-height:180px;"></td><td>Position ab 1, nicht gefunden ergibt 0. Unicode-Codepunkte.</td></tr><tr><td><strong>Zeichen lesen</strong><br><code>ugso_text_char</code></td><td><img src="'+D+'" alt="Zeichen lesen" style="max-width:280px;max-height:180px;"></td><td>Zeichen ab 1 vom Anfang/Ende, erstes/letztes oder zufälliges Zeichen. Außerhalb ergibt leeren Text.</td></tr><tr><td><strong>Teiltext</strong><br><code>ugso_text_slice</code></td><td><img src="'+O+'" alt="Teiltext" style="max-width:280px;max-height:180px;"></td><td>Inklusive Grenzen ab 1 vom Anfang. Ungültige/umgekehrte Grenzen ergeben leeren Text.</td></tr><tr><td><strong>Groß-/Klein-/Titelbuchstaben</strong><br><code>ugso_text_case</code></td><td><img src="'+L+'" alt="Groß-/Klein-/Titelbuchstaben" style="max-width:280px;max-height:180px;"></td><td>Unicode-Text in Groß-, Klein- oder Titelbuchstaben umwandeln.</td></tr><tr><td><strong>Leerraum entfernen</strong><br><code>ugso_text_trim</code></td><td><img src="'+N+'" alt="Leerraum entfernen" style="max-width:280px;max-height:180px;"></td><td>Entfernt äußeren Leerraum einschließlich Tabs und Zeilenumbrüchen.</td></tr><tr><td><strong>Text zählen</strong><br><code>ugso_text_count</code></td><td><img src="'+J+'" alt="Text zählen" style="max-width:280px;max-height:180px;"></td><td>Zählt nicht überlappende Treffer; leerer Suchtext ergibt 0.</td></tr><tr><td><strong>Text ersetzen</strong><br><code>ugso_text_replace</code></td><td><img src="'+F+'" alt="Text ersetzen" style="max-width:280px;max-height:180px;"></td><td>Ersetzt alle wörtlichen Treffer, ohne Regex. Leerer Suchtext lässt den Text unverändert.</td></tr><tr><td><strong>Text umkehren</strong><br><code>ugso_text_reverse</code></td><td><img src="'+W+'" alt="Text umkehren" style="max-width:280px;max-height:180px;"></td><td>Zusätzlicher Blockly-Standardblock. Kehrt Unicode-Codepunkte um, nicht zusammengesetzte Grapheme.</td></tr><tr><td><strong>Listenelement wiederholen</strong><br><code>ugso_list_repeat</code></td><td><img src="'+I+'" alt="Listenelement wiederholen" style="max-width:280px;max-height:180px;"></td><td>Neue Liste mit 0–10000 Wiederholungen eines Wertes.</td></tr><tr><td><strong>Listenelement suchen</strong><br><code>ugso_list_index</code></td><td><img src="'+V+'" alt="Listenelement suchen" style="max-width:280px;max-height:180px;"></td><td>Position ab 1, nicht gefunden ergibt 0. HA/Python-Gleichheit statt JavaScript-Referenzgleichheit.</td></tr><tr><td><strong>Listenelement lesen</strong><br><code>ugso_list_get</code></td><td><img src="'+q+'" alt="Listenelement lesen" style="max-width:280px;max-height:180px;"></td><td>Liest ab 1 vom Anfang/Ende, erstes/letztes oder zufälliges Element. Außerhalb/leere Liste ergibt null.</td></tr><tr><td><strong>Listenelement setzen/einfügen</strong><br><code>ugso_list_set</code></td><td><img src="'+U+'" alt="Listenelement setzen/einfügen" style="max-width:280px;max-height:180px;"></td><td>Weist eine neue Liste mit ersetzt/eingefügtem Wert zu. Index ab 1; Einfügen erlaubt Länge+1. Ungültiger Index lässt die Liste unverändert.</td></tr><tr><td><strong>Listenelement entfernen</strong><br><code>ugso_list_remove</code></td><td><img src="'+M+'" alt="Listenelement entfernen" style="max-width:280px;max-height:180px;"></td><td>Weist eine neue Liste ohne dieses Element zu. Index ab 1, ungültiger Index lässt die Liste unverändert.</td></tr><tr><td><strong>Teilliste</strong><br><code>ugso_list_slice</code></td><td><img src="'+P+'" alt="Teilliste" style="max-width:280px;max-height:180px;"></td><td>Kopie eines Bereichs, inklusive Grenzen ab 1 vom Anfang. Umgekehrte/ungültige Grenzen ergeben eine leere Liste.</td></tr><tr><td><strong>Liste/Text teilen/verbinden</strong><br><code>ugso_list_split</code></td><td><img src="'+G+'" alt="Liste/Text teilen/verbinden" style="max-width:280px;max-height:180px;"></td><td>Text anhand eines wörtlichen Trennzeichens teilen oder Liste verbinden. Leeres Trennzeichen teilt in Unicode-Zeichen.</td></tr><tr><td><strong>Liste sortieren</strong><br><code>ugso_list_sort</code></td><td><img src="'+K+'" alt="Liste sortieren" style="max-width:280px;max-height:180px;"></td><td>Neue sortierte Liste; Original bleibt erhalten. Numerischer Modus verlangt Zahlen, Textmodus wandelt Elemente in Text um.</td></tr><tr><td><strong>Liste umkehren</strong><br><code>ugso_list_reverse</code></td><td><img src="'+R+'" alt="Liste umkehren" style="max-width:280px;max-height:180px;"></td><td>Neue Liste in umgekehrter Reihenfolge; Original bleibt erhalten.</td></tr><tr><td><strong>Zählschleife</strong><br><code>ugso_for_range</code></td><td><img src="'+C+'" alt="Zählschleife" style="max-width:280px;max-height:180px;"></td><td>Feste ganze Grenzen, inklusive Ende wenn auf dem Schrittraster. Auf-/absteigend automatisch, Schrittbetrag &gt;0, höchstens 10000 Durchläufe. HA repeat.for_each mit Variable pro Durchlauf.</td></tr><tr><td><strong>Für jeden Wert mit Variable</strong><br><code>ugso_foreach_variable</code></td><td><img src="'+Y+'" alt="Für jeden Wert mit Variable" style="max-width:280px;max-height:180px;"></td><td>HA repeat.for_each mit benannter Variable, vor dem Körper aus repeat.item gesetzt. Wiederverwendung derselben Variable in verschachtelten Schleifen vermeiden.</td></tr></tbody></table><h2 id="ablaufe-objekte-und-listen-seit-0-1-13" tabindex="-1">Abläufe, Objekte und Listen seit 0.1.13 <a class="header-anchor" href="#ablaufe-objekte-und-listen-seit-0-1-13" aria-label="Permalink to &quot;Abläufe, Objekte und Listen seit 0.1.13&quot;">​</a></h2><p><a href="./flow">ioBroker / Original-Blockly / native HA: Gegenüberstellung und Grenzen</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Pause</strong><br><code>ugso_pause</code></td><td><img src="'+Q+'" alt="Pause" style="max-width:280px;max-height:180px;"></td><td>Dauer mit ms/Sekunden/Minuten/Stunden; konstante oder berechnete Zahl. Native HA-Wartezeit.</td></tr><tr><td><strong>Warte bis</strong><br><code>ugso_wait</code></td><td><img src="'+$+'" alt="Warte bis" style="max-width:280px;max-height:180px;"></td><td>Boolean-Bedingung mit Timeout und Haken zum Fortsetzen; ohne Haken endet der Lauf bei Timeout.</td></tr><tr><td><strong>Diesen Lauf stoppen</strong><br><code>ugso_stop</code></td><td><img src="'+X+'" alt="Diesen Lauf stoppen" style="max-width:280px;max-height:180px;"></td><td>Grund und optionaler Fehler-Haken. Beendet den gesamten Lauf, auch in Schleifen.</td></tr><tr><td><strong>Wiederhole Anzahl</strong><br><code>ugso_repeat</code></td><td><img src="'+ee+'" alt="Wiederhole Anzahl" style="max-width:280px;max-height:180px;"></td><td>C-Körper für HA-repeat.count; repeat.index ist der 1-basierte Index.</td></tr><tr><td><strong>Wiederhole solange/bis</strong><br><code>ugso_repeat_while</code></td><td><img src="'+te+'" alt="Wiederhole solange/bis" style="max-width:280px;max-height:180px;"></td><td>Boolean-Eingang und Aktionskörper. Solange prüft vorher, bis danach. Pause im Körper verwenden.</td></tr><tr><td><strong>Für jeden Eintrag</strong><br><code>ugso_foreach</code></td><td><img src="'+re+'" alt="Für jeden Eintrag" style="max-width:280px;max-height:180px;"></td><td>Liste durchlaufen; aktueller Wert über Template repeat.item, Index über repeat.index.</td></tr><tr><td><strong>Neues Objekt</strong><br><code>ugso_object_new</code></td><td><img src="'+ne+'" alt="Neues Objekt" style="max-width:280px;max-height:180px;"></td><td>0–100 benannte Attribute mit Zahnrad/+−. Dictionary-Wert, keine HA-Entität.</td></tr><tr><td><strong>Attribut von Objekt</strong><br><code>ugso_object_get</code></td><td><img src="'+ie+'" alt="Attribut von Objekt" style="max-width:280px;max-height:180px;"></td><td>Schlüssel lesen; fehlender Schlüssel ergibt null. Dictionary erforderlich.</td></tr><tr><td><strong>Objekt hat Attribut</strong><br><code>ugso_object_has</code></td><td><img src="'+ae+'" alt="Objekt hat Attribut" style="max-width:280px;max-height:180px;"></td><td>Boolean-Test auf einen Dictionary-Schlüssel.</td></tr><tr><td><strong>Attribute des Objekts</strong><br><code>ugso_object_keys</code></td><td><img src="'+se+'" alt="Attribute des Objekts" style="max-width:280px;max-height:180px;"></td><td>Schlüsselliste für Listen- und Für-jeden-Eintrag-Blocks.</td></tr><tr><td><strong>Setze Attribut in Variable</strong><br><code>ugso_object_set</code></td><td><img src="'+de+'" alt="Setze Attribut in Variable" style="max-width:280px;max-height:180px;"></td><td>Variablenauswahl und Wertanschluss; weist eine Dictionary-Kopie mit geändertem Schlüssel zu. Vorher als Objekt setzen.</td></tr><tr><td><strong>Entferne Attribut aus Variable</strong><br><code>ugso_object_remove</code></td><td><img src="'+oe+'" alt="Entferne Attribut aus Variable" style="max-width:280px;max-height:180px;"></td><td>Neue Zuweisung ohne Schlüssel. Keine Mutation anderer Variablen oder Entity-Attribute.</td></tr><tr><td><strong>Bereichsvergleich</strong><br><code>ugso_logic_range</code></td><td><img src="'+le+'" alt="Bereichsvergleich" style="max-width:280px;max-height:180px;"></td><td>Unabhängig &lt; oder ≤ für Unter- und Obergrenze; Zahl und Laufzeitzahl.</td></tr><tr><td><strong>Ersatzwert</strong><br><code>ugso_logic_default</code></td><td><img src="'+ge+'" alt="Ersatzwert" style="max-width:280px;max-height:180px;"></td><td>Auswahl null/nicht gesetzt oder leer/falsch/0; null-Modus erhält gültige 0 und falsch.</td></tr><tr><td><strong>Der Fall ist</strong><br><code>ugso_case</code></td><td><img src="'+he+'" alt="Der Fall ist" style="max-width:280px;max-height:180px;"></td><td>1–100 Fallwerte mit Zahnrad/+− und Aktionskörpern. Erste Übereinstimmung, sonst optionaler Standardkörper.</td></tr><tr><td><strong>Liste erstellen</strong><br><code>ugso_list_new</code></td><td><img src="'+ue+'" alt="Liste erstellen" style="max-width:280px;max-height:180px;"></td><td>0–100 beliebige Einträge mit Zahnrad/+−, auch verschachtelte Werte.</td></tr><tr><td><strong>Listenlänge</strong><br><code>ugso_list_length</code></td><td><img src="'+ce+'" alt="Listenlänge" style="max-width:280px;max-height:180px;"></td><td>Länge einer Liste als Laufzeitzahl. Texte und Dictionaries sind keine Listen.</td></tr><tr><td><strong>Liste ist leer</strong><br><code>ugso_list_empty</code></td><td><img src="'+me+'" alt="Liste ist leer" style="max-width:280px;max-height:180px;"></td><td>Boolean-Prüfung auf eine Liste ohne Einträge.</td></tr></tbody></table><h2 id="konvertierung-seit-0-1-12" tabindex="-1">Konvertierung seit 0.1.12 <a class="header-anchor" href="#konvertierung-seit-0-1-12" aria-label="Permalink to &quot;Konvertierung seit 0.1.12&quot;">​</a></h2><p><a href="./conversion">Anleitung, ioBroker-Gegenüberstellung und vorgemerktes JSONata</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Nach Zahl</strong><br><code>ugso_convert_number</code></td><td><img src="'+pe+'" alt="Nach Zahl" style="max-width:280px;max-height:180px;"></td><td>HA float ohne Ersatzwert; vollständige Zahl mit Dezimalpunkt. Laufzeitzahl für Variablen, Vergleiche und Zeitrechnung.</td></tr><tr><td><strong>Nach Logikwert</strong><br><code>ugso_convert_boolean</code></td><td><img src="'+be+'" alt="Nach Logikwert" style="max-width:280px;max-height:180px;"></td><td>HA bool; erkannte Boolean-/Textwerte. Boolean-Ausgang für Bedingungen und Logik.</td></tr><tr><td><strong>Nach String</strong><br><code>ugso_convert_string</code></td><td><img src="'+xe+'" alt="Nach String" style="max-width:280px;max-height:180px;"></td><td>Jinja-Textdarstellung eines Werts; keine JSON-Serialisierung.</td></tr><tr><td><strong>Typ von</strong><br><code>ugso_convert_type</code></td><td><img src="'+_e+'" alt="Typ von" style="max-width:280px;max-height:180px;"></td><td>HA typeof liefert Python-Typnamen, z. B. str, float, bool, dict. Ab HA 2023.4.</td></tr><tr><td><strong>Nach Datum/Zeit</strong><br><code>ugso_convert_datetime</code></td><td><img src="'+fe+'" alt="Nach Datum/Zeit" style="max-width:280px;max-height:180px;"></td><td>ISO-Text oder Unix-Sekunden/-Millisekunden nach HA-Ortszeit. Typisierter Time-Ausgang.</td></tr><tr><td><strong>Datum/Zeit nach …</strong><br><code>ugso_convert_date_format</code></td><td><img src="'+ke+'" alt="Datum/Zeit nach …" style="max-width:280px;max-height:180px;"></td><td>Datumswert, Format, Unix-Zahl oder Datumsbestandteil. Auswahl wechselt den Ausgangstyp; eigenes Format zeigt ein Textfeld.</td></tr><tr><td><strong>Zeitdifferenz formatieren</strong><br><code>ugso_convert_duration</code></td><td><img src="'+we+'" alt="Zeitdifferenz formatieren" style="max-width:280px;max-height:180px;"></td><td>Dauer in Millisekunden oder Sekunden nach hh:mm:ss, hh:mm, mm:ss. Vorzeichen und große Stunden/Minuten bleiben erhalten.</td></tr><tr><td><strong>JSON nach Wert</strong><br><code>ugso_convert_from_json</code></td><td><img src="'+Ae+'" alt="JSON nach Wert" style="max-width:280px;max-height:180px;"></td><td>JSON-Text nach Objekt, Liste oder Einzelwert. Ungültiges JSON erzeugt einen HA-Fehler.</td></tr><tr><td><strong>Wert nach JSON</strong><br><code>ugso_convert_to_json</code></td><td><img src="'+ze+'" alt="Wert nach JSON" style="max-width:280px;max-height:180px;"></td><td>JSON-Serialisierung mit Checkbox für Einrückung. Datumswerte vorher formatieren.</td></tr></tbody></table><h2 id="datum-und-zeit-seit-0-1-11" tabindex="-1">Datum und Zeit seit 0.1.11 <a class="header-anchor" href="#datum-und-zeit-seit-0-1-11" aria-label="Permalink to &quot;Datum und Zeit seit 0.1.11&quot;">​</a></h2><p>Die violetten Zeit-Blocks verwenden einen eigenen typisierten Datumswert-Anschluss. <a href="./time">Bedienung, Grenzfälle und Gegenüberstellung</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Uhrzeitvergleich</strong><br><code>ugso_time_compare</code></td><td><img src="'+ye+'" alt="Uhrzeitvergleich" style="max-width:280px;max-height:180px;"></td><td>Feste Uhrzeit HH:mm/HH:mm:ss; kleiner, größer, gleich oder Zeitraum. Ende erscheint nur bei zwischen/nicht zwischen.</td></tr><tr><td><strong>Uhrzeitvergleich mit Eingängen</strong><br><code>ugso_time_compare_input</code></td><td><img src="'+ve+'" alt="Uhrzeitvergleich mit Eingängen" style="max-width:280px;max-height:180px;"></td><td>Uhrzeitgrenzen als Text-Blocks. Haken aus: eigener Datumswert-Eingang erscheint. Zeiträume auch über Mitternacht.</td></tr><tr><td><strong>Aktuelle Zeit als Datumswert</strong><br><code>ugso_time_now</code></td><td><img src="'+Be+'" alt="Aktuelle Zeit als Datumswert" style="max-width:280px;max-height:180px;"></td><td>HA-Ortszeit mit Datum und Zeitzone, Time-Ausgang für Berechnung oder Formatierung.</td></tr><tr><td><strong>Berechnete Zeit</strong><br><code>ugso_time_boundary</code></td><td><img src="'+Se+'" alt="Berechnete Zeit" style="max-width:280px;max-height:180px;"></td><td>Beginn von Tag, nächstem Tag, Woche (Montag), Monat oder Jahr in HA-Ortszeit.</td></tr><tr><td><strong>Nächste Sonnenzeit</strong><br><code>ugso_time_sun</code></td><td><img src="'+Te+'" alt="Nächste Sonnenzeit" style="max-width:280px;max-height:180px;"></td><td>Aufgang, Untergang, Dämmerung, Höchststand oder Sonnenmitternacht aus sun.sun. Minutenoffset; kann morgen sein.</td></tr><tr><td><strong>Zeit berechnen</strong><br><code>ugso_time_shift</code></td><td><img src="'+He+'" alt="Zeit berechnen" style="max-width:280px;max-height:180px;"></td><td>Datumswert gear Zahl in Millisekunden, Sekunden, Minuten, Stunden oder Tagen.</td></tr><tr><td><strong>Zeit formatieren</strong><br><code>ugso_time_format</code></td><td><img src="'+Ee+'" alt="Zeit formatieren" style="max-width:280px;max-height:180px;"></td><td>Datumswert als Uhrzeit, Datum, Datum/Uhrzeit, ISO mit Zeitzone oder Unix-Sekunden.</td></tr></tbody></table><h2 id="weitere-blocks" tabindex="-1">Weitere Blocks <a class="header-anchor" href="#weitere-blocks" aria-label="Permalink to &quot;Weitere Blocks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Bild im Editor</th><th>Funktionsbeschreibung</th></tr></thead><tbody><tr><td><strong>Automation</strong><br><code>ugso_automation</code></td><td><img src="'+Ze+'" alt="Automation" style="max-width:280px;max-height:180px;"></td><td>Rahmen mit Auslösern, optionaler Bedingung und Aktionskette. Name, ID, Beschreibung und Modus stehen außerhalb des Blocks.</td></tr><tr><td><strong>Zustand erreicht</strong><br><code>ugso_state_trigger</code></td><td><img src="'+je+'" alt="Zustand erreicht" style="max-width:280px;max-height:180px;"></td><td>Startet, wenn die Entität den eingetragenen Zustand erreicht. Erzeugt <code>trigger: state</code> mit <code>to</code>.</td></tr><tr><td><strong>Zahl über/unter Grenze</strong><br><code>ugso_numeric_trigger</code></td><td><img src="'+De+'" alt="Zahl über/unter Grenze" style="max-width:280px;max-height:180px;"></td><td>Startet beim Grenzübertritt, nicht fortlaufend. Grenze als Number-Wert; <code>trigger: numeric_state</code>.</td></tr><tr><td><strong>Uhrzeit</strong><br><code>ugso_time_trigger</code></td><td><img src="'+Oe+'" alt="Uhrzeit" style="max-width:280px;max-height:180px;"></td><td>Täglicher Uhrzeit-Auslöser, HH:MM oder HH:MM:SS; <code>trigger: time</code>.</td></tr><tr><td><strong>Sonnenaufgang/-untergang</strong><br><code>ugso_sun_trigger</code></td><td><img src="'+Le+'" alt="Sonnenaufgang/-untergang" style="max-width:280px;max-height:180px;"></td><td>Dropdown für Sonnenaufgang oder Sonnenuntergang; <code>trigger: sun</code>.</td></tr><tr><td><strong>HA startet</strong><br><code>ugso_start_trigger</code></td><td><img src="'+Ne+'" alt="HA startet" style="max-width:280px;max-height:180px;"></td><td>Startet beim Home-Assistant-Start; <code>trigger: homeassistant</code>.</td></tr><tr><td><strong>Zustand ist</strong><br><code>ugso_state_condition</code></td><td><img src="'+Je+'" alt="Zustand ist" style="max-width:280px;max-height:180px;"></td><td>Boolean-Bedingung: Entität hat den angegebenen Zustand; <code>condition: state</code>.</td></tr><tr><td><strong>Zahlenvergleich</strong><br><code>ugso_numeric_condition</code></td><td><img src="'+Fe+'" alt="Zahlenvergleich" style="max-width:280px;max-height:180px;"></td><td>Boolean-Bedingung über/unter einer Grenze; <code>condition: numeric_state</code>.</td></tr><tr><td><strong>UND / ODER / NICHT</strong><br><code>ugso_logic_condition</code></td><td><img src="'+We+'" alt="UND / ODER / NICHT" style="max-width:280px;max-height:180px;"></td><td>Verknüpft 1–100 Bedingungen. Das Zahnrad ergänzt, entfernt und ordnet Eingänge um. <code>and</code>, <code>or</code>, <code>not</code>.</td></tr><tr><td><strong>Datum heute</strong><br><code>ugso_date_condition</code></td><td><img src="'+Ie+'" alt="Datum heute" style="max-width:280px;max-height:180px;"></td><td>Datumsauswahl mit ist/ab/bis einschließlich Jahr. HA-Template vergleicht das heutige Datum in der HA-Zeitzone. Kein eigener Auslöser.</td></tr><tr><td><strong>Zahl</strong><br><code>ugso_number</code></td><td><img src="'+Ve+'" alt="Zahl" style="max-width:280px;max-height:180px;"></td><td>Unbegrenzter Zahlen-Wertblock. Passt in Grenzen und Wartezeiten; deren eigene Validierung gilt weiterhin.</td></tr><tr><td><strong>Prozent</strong><br><code>ugso_percent</code></td><td><img src="'+qe+'" alt="Prozent" style="max-width:280px;max-height:180px;"></td><td>Slider und genaue Eingabe für ganze Werte 0–100. Number-Output, beispielsweise für Ladezustand oder Helligkeit.</td></tr><tr><td><strong>Text</strong><br><code>ugso_text</code></td><td><img src="'+Ue+'" alt="Text" style="max-width:280px;max-height:180px;"></td><td>Seit 0.1.65 ein leeres, einzeiliges Eingabefeld zwischen Anführungszeichen, ohne zusätzliche Hinweiszeile. Enter übernimmt. Bereits gespeicherte Texte bleiben bei Projekt-/YAML-Import erhalten, auch mit Zeilenumbrüchen.</td></tr><tr><td><strong>Farbe</strong><br><code>ugso_colour</code></td><td><img src="'+Me+'" alt="Farbe" style="max-width:280px;max-height:180px;"></td><td>Hex-Farbauswahl; als RGB-Liste für Licht, Variablen oder Farbberechnungen. Colour/Value-Ausgang, nicht an feste Zahlenanschlüsse.</td></tr><tr><td><strong>Ein / Aus / Umschalten</strong><br><code>ugso_switch_action</code></td><td><img src="'+Pe+'" alt="Ein / Aus / Umschalten" style="max-width:280px;max-height:180px;"></td><td>Aktion der Entitätsdomain: <code>turn_on</code>, <code>turn_off</code> oder <code>toggle</code>. Die Entität muss die Aktion unterstützen.</td></tr><tr><td><strong>Generische HA-Aktion</strong><br><code>ugso_service_action</code></td><td><img src="'+Ge+'" alt="Generische HA-Aktion" style="max-width:280px;max-height:180px;"></td><td>Aktionsname, optional eine Zielentität, Daten als JSON-Objekt. Für Parameter, die Komfortblocks noch nicht anbieten.</td></tr><tr><td><strong>Warte Sekunden</strong><br><code>ugso_delay_action</code></td><td><img src="'+Ke+'" alt="Warte Sekunden" style="max-width:280px;max-height:180px;"></td><td>Pause von 0–86400 ganzen Sekunden. Number-Eingang mit Shadow-Standardwert.</td></tr><tr><td><strong>Log-Ausgabe</strong><br><code>ugso_log_action</code></td><td><img src="'+Re+'" alt="Log-Ausgabe" style="max-width:280px;max-height:180px;"></td><td>Textmeldung und Schweregrad-Dropdown; <code>system_log.write</code>. Info/Debug können in HA gefiltert sein.</td></tr><tr><td><strong>HA-Script steuern</strong><br><code>ugso_script_action</code></td><td><img src="'+Ce+'" alt="HA-Script steuern" style="max-width:280px;max-height:180px;"></td><td>Starten ohne Warten, stoppen oder direkt aufrufen und warten. <code>script.turn_on</code>, <code>script.turn_off</code> oder <code>script.name</code>.</td></tr><tr><td><strong>Entität aktualisieren</strong><br><code>ugso_update_action</code></td><td><img src="'+Ye+'" alt="Entität aktualisieren" style="max-width:280px;max-height:180px;"></td><td><code>homeassistant.update_entity</code> fordert ein Update an. Setzt keinen Zustand; Unterstützung hängt von der Integration ab.</td></tr><tr><td><strong>Helfer steuern</strong><br><code>ugso_helper_action</code></td><td><img src="'+Qe+'" alt="Helfer steuern" style="max-width:280px;max-height:180px;"></td><td>Typ-Dropdown Schalter/Zähler/Timer steuert das Aktions-Dropdown. Entitäts-ID muss zum Typ passen. Timer nutzt vorhandene Dauer; Parameter über generische Aktion.</td></tr><tr><td><strong>Licht mit Farbe</strong><br><code>ugso_colour_action</code></td><td><img src="'+$e+'" alt="Licht mit Farbe" style="max-width:280px;max-height:180px;"></td><td>Lichtentität, Colour-Eingang und Helligkeit 0–100. Erzeugt <code>light.turn_on</code> mit <code>rgb_color</code> und <code>brightness_pct</code>. Farbunterstützung des Geräts erforderlich.</td></tr></tbody></table><p>Bei Minus oder ausgeschaltetem Sonst werden angeschlossene Blocks abgelöst, nicht gelöscht. Wieder verbinden oder entfernen, bevor YAML exportiert wird. Rückgängig stellt Anschlüsse und Verbindungen wieder her. Shadow-Werte kehren zurück, wenn ein ersetzender Wertblock entfernt wird.</p><h2 id="variablen-und-template-blocks-seit-0-1-8" tabindex="-1">Variablen- und Template-Blocks seit 0.1.8 <a class="header-anchor" href="#variablen-und-template-blocks-seit-0-1-8" aria-label="Permalink to &quot;Variablen- und Template-Blocks seit 0.1.8&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Bild im Editor</th><th>Funktionsbeschreibung</th></tr></thead><tbody><tr><td><strong>Variable setzen</strong><br><code>ugso_variable_set</code></td><td><img src="'+Xe+'" alt="Variable setzen" style="max-width:280px;max-height:180px;"></td><td>Aktionsblock: ausgewählte Variable auf Zahl, Text/Template, Boolean oder null setzen. Erzeugt eine native HA-<code>variables</code>-Aktion. Vor späteren Lesezugriffen platzieren.</td></tr><tr><td><strong>Variable lesen</strong><br><code>ugso_variable_get</code></td><td><img src="'+et+'" alt="Variable lesen" style="max-width:280px;max-height:180px;"></td><td>Seitlicher String-Anschluss; erzeugt <code>{{ name }}</code> für Log-Meldungen und weitere Variablenzuweisungen. Dropdown bietet Umbenennen/Löschen.</td></tr><tr><td><strong>Jinja – eigener Code</strong><br><code>ugso_template</code></td><td><img src="'+dr+'" alt="Jinja – eigener Code" style="max-width:280px;max-height:180px;"></td><td>Mehrzeiliges Jinja-Template mit String-Anschluss für Log-Meldungen oder Variablenzuweisungen. HA wertet die Vorlage bei Ausführung aus; Blocks führt sie nicht aus.</td></tr><tr><td><strong>Jinja – eigene Bedingung</strong><br><code>ugso_template_condition</code></td><td><img src="'+or+'" alt="Jinja – eigene Bedingung" style="max-width:280px;max-height:180px;"></td><td>Boolean-Anschluss für Nur wenn, Falls und logische Gruppen. Erzeugt <code>condition: template</code> mit <code>value_template</code>. Ergebnis muss in HA wahr sein; kein eigener Auslöser.</td></tr></tbody></table><h2 id="variablen-und-templates-verwenden" tabindex="-1">Variablen und Templates verwenden <a class="header-anchor" href="#variablen-und-templates-verwenden" aria-label="Permalink to &quot;Variablen und Templates verwenden&quot;">​</a></h2><h3 id="erhohen-und-verringern-seit-0-1-10" tabindex="-1">Erhöhen und Verringern seit 0.1.10 <a class="header-anchor" href="#erhohen-und-verringern-seit-0-1-10" aria-label="Permalink to &quot;Erhöhen und Verringern seit 0.1.10&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Block</th><th>Bild im Editor</th><th>Funktionsbeschreibung</th></tr></thead><tbody><tr><td><strong>Erhöhe Variable um …</strong><br><code>ugso_variable_change</code></td><td><img src="'+tt+'" alt="Erhöhe Variable um" style="max-width:280px;max-height:180px;"></td><td>Dropdown für die Variable, Number-Eingang mit Standard-Schritt <code>1</code>. Addiert den Schritt zur zuvor gesetzten Zahlenvariable. Negative Schritte verringern; <code>0</code> und Dezimalschritte sind möglich. Native HA-Variablenzuweisung mit Jinja.</td></tr></tbody></table><p>Im Menü <strong>Variablen</strong> erscheinen für jede erstellte Variable <strong>Setze</strong>, <strong>Erhöhe</strong> und <strong>Variable lesen</strong>. Beispiel in der Aktionskette: <strong>Setze test auf 10 → Erhöhe test um 1 → Log Info Meldung Variable test</strong>. Die Meldung verwendet anschließend den Wert <code>11</code>. Mit Schritt <code>-2</code> würde aus <code>10</code> der Wert <code>8</code>.</p><p>Vor dem Erhöhen die Variable als Zahl setzen. Fehlende Variablen, Text (auch <code>&quot;10&quot;</code>), Boolean oder null werden nicht automatisch konvertiert oder mit <code>0</code> initialisiert; die Jinja-Auswertung in HA schlägt dann fehl. Erstellen allein weist keinen Wert zu. JSON erhält den Erhöhen-Block; unser genaues YAML-Ausgabeformat wird beim Import wieder als Erhöhen-Block erkannt. Andere Rechenvorlagen bleiben Template-Blocks. Der geplante Dialog für typisierte Variablen bleibt offen.</p><p>Im Menü <strong>Variablen → Variable erstellen …</strong> beispielsweise <code>leistung</code> anlegen. Namen verwenden Buchstaben, Ziffern und <code>_</code>, keine führende Ziffer. Den Setzen-Block in <strong>Dann</strong> platzieren und eine Zahl oder ein Template anschließen. Danach den Lesen-Block in eine Log-Meldung stecken. Erstellen allein weist noch keinen Wert zu. Variablen gelten für den HA-Automationslauf; sie ersetzen keine dauerhaft gespeicherten Helfer.</p><p>Beispiel: <strong>Setze leistung auf Template</strong> mit <code>{{ states(&#39;sensor.leistung&#39;) | float(0) }}</code>, danach <strong>Log Info Meldung Variable leistung</strong>. HA liest den Sensor beim Setzen und verwendet den Wert im folgenden Schritt. Eine Template-Bedingung kann beispielsweise <code>{{ states(&#39;sensor.leistung&#39;) | float(0) &gt; 100 }}</code> prüfen.</p><p>Umbenennen aktualisiert die verbundenen Variablen-Blocks. Namen in frei eingegebenen Jinja-Texten müssen manuell geändert werden. Aktionsvariablen stehen erst nach ihrer Zuweisung bereit, nicht in vorgelagerten Automationsbedingungen. Blocks prüft Struktur und YAML, keine Jinja-Syntax oder vorhandenen HA-Entitäten. Der Import unterstützt pro Variablenwert Text/Template, Zahl, Boolean oder null. Mehrere Einträge werden seit 0.1.34 im gemeinsamen JSON-Block unterstützt. Listen/Objekte als Werte und Variablen auf Automationsebene werden weiterhin abgelehnt. <a href="https://www.home-assistant.io/docs/scripts/#define-variables" target="_blank" rel="noreferrer">Native HA-Variablen und Gültigkeit</a>.</p><h2 id="logik-blocks-seit-0-1-9" tabindex="-1">Logik-Blocks seit 0.1.9 <a class="header-anchor" href="#logik-blocks-seit-0-1-9" aria-label="Permalink to &quot;Logik-Blocks seit 0.1.9&quot;">​</a></h2><p>Seit <strong>0.1.57</strong> stehen die Eingänge der erweiterbaren UND-/ODER-Gruppe nebeneinander, mit „und“ bzw. „oder“ dazwischen. Das Auswahlfeld enthält nur „und / oder / nicht“. Im Zahnrad-Popup tragen die Zweigbausteine denselben Operator statt „Bedingung“, auch in EN/FR. Die HA-Verknüpfung bleibt unverändert.</p><p>Seit <strong>0.1.56</strong> steht hier auch der erweiterbare Falls-Block. Logik ist in Standard/Dark blau, Objekte braun. <a href="./themes">Farben und Erweiterbarkeit</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild im Editor</th><th>Funktionsbeschreibung</th></tr></thead><tbody><tr><td><strong>Falls / sonst falls / sonst</strong><br><code>ugso_if_action</code></td><td><img src="'+rt+'" alt="Falls / sonst falls / sonst" style="max-width:280px;max-height:180px;"></td><td>Das Zahnrad ergänzt, entfernt und ordnet sonst-falls-Zweige um und fügt Sonst hinzu. <code>if</code> oder <code>choose</code>, erster passender Zweig.</td></tr><tr><td><strong>Vergleich</strong><br><code>ugso_compare</code></td><td><img src="'+nt+'" alt="Vergleich" style="max-width:280px;max-height:180px;"></td><td>Vergleicht zwei Werte mit =, ≠, &lt;, ≤, &gt; oder ≥. Zahlen, Texte, Variablen und einzelne Template-Ausdrücke anschließen. Liefert Boolean; Ausgabe als HA-Template-Bedingung oder Variablenwert.</td></tr><tr><td><strong>UND / ODER kompakt</strong><br><code>ugso_binary_logic</code></td><td><img src="'+it+'" alt="UND ODER kompakt" style="max-width:280px;max-height:180px;"></td><td>Nur für bestehende Projekte; aus der Blockauswahl entfernt. Stattdessen die erweiterbare UND-/ODER-Gruppe verwenden.</td></tr><tr><td><strong>NICHT</strong><br><code>ugso_not</code></td><td><img src="'+at+'" alt="NICHT" style="max-width:280px;max-height:180px;"></td><td>Negiert eine Boolean-Bedingung. Als Bedingung native HA-<code>not</code>-Gruppe, als Variablenwert Jinja-<code>not</code>.</td></tr><tr><td><strong>wahr / falsch</strong><br><code>ugso_boolean</code></td><td><img src="'+st+'" alt="wahr falsch" style="max-width:280px;max-height:180px;"></td><td>Boolean-Konstante mit Dropdown. Für Bedingungen und Variablen; die Zuweisung erzeugt echte YAML-Boolean-Werte.</td></tr><tr><td><strong>null</strong><br><code>ugso_null</code></td><td><img src="'+dt+'" alt="null" style="max-width:280px;max-height:180px;"></td><td>Kein Wert. Variablen erhalten YAML <code>null</code>, Ausdrücke Jinja <code>none</code>. Weder <code>0</code> noch <code>falsch</code>; kein Boolean-Bedingungsblock.</td></tr><tr><td><strong>Wenn → dann Wert → sonst Wert</strong><br><code>ugso_ternary</code></td><td><img src="'+ot+'" alt="Bedingte Wertauswahl" style="max-width:280px;max-height:180px;"></td><td>Wählt anhand einer Boolean-Bedingung einen von zwei Werten. Für Variablen, Log-Meldungen und Vergleiche; erzeugt einen Jinja-Ausdruck und enthält keine Aktionskette.</td></tr></tbody></table><p><strong>Beispiel:</strong> In der Aktionskette zuerst <code>leistung</code> setzen. Dann <strong>Setze meldung auf Wenn</strong>, mit <strong>Vergleich Variable leistung &gt; Zahl 100</strong> als Test, Text <strong>Hohe Leistung</strong> als Dann-Wert und Text <strong>Geringe Leistung</strong> als Sonst-Wert. Danach <strong>Log Info Meldung Variable meldung</strong> verwenden. HA entscheidet bei Ausführung.</p><p>Vergleiche konvertieren Typen nicht automatisch: Zahl <code>20</code> unterscheidet sich von Text <code>&quot;20&quot;</code>. Sensorzustände gegebenenfalls im Template mit <code>float</code> oder <code>int</code> umwandeln. In einem Ausdruckseingang ist nur eine einzelne Jinja-Ausgabe zulässig, beispielsweise <code>{{ states(&#39;sensor.leistung&#39;) | float(0) }}</code>. Mehrzeilige Anweisungen und gemischter Text bleiben im eigenständigen Template-Wertblock nutzbar. Dynamische Wertauswahlen sind nicht als feste Zahlen-Grenzen oder Wartezeiten vorgesehen.</p><p>JSON-Projekte bewahren die Blockformen und Anschlüsse. YAML speichert die native Bedeutung: Beim Wiederöffnen erscheinen Vergleiche und Wertauswahlen als Template-Blocks, UND/ODER/NICHT als Bedingungsgruppen. <a href="https://www.home-assistant.io/docs/scripts/conditions/#logical-conditions" target="_blank" rel="noreferrer">HA-Logikbedingungen</a>.</p><h2 id="originalplugins-und-einbindung" tabindex="-1">Originalplugins und Einbindung <a class="header-anchor" href="#originalplugins-und-einbindung" aria-label="Permalink to &quot;Originalplugins und Einbindung&quot;">​</a></h2><p>Die sechs bisherigen Originalplugins sind auf <strong>13.2.0</strong>, die vier Theme-/Zoom-Plugins und die Arbeitsbereichssuche auf <strong>13.3.0</strong> festgelegt und werden lokal mit Blockly <strong>13.3.0</strong> ausgeliefert. Lizenz: Apache-2.0. Die folgenden Links führen direkt zu den Original-Repositories. Unsere HA-Blocks, YAML-Adapter und Zahnrad-Baukästen sind eigener UGSo-Code.</p><table tabindex="0"><thead><tr><th>Originalplugin</th><th>Nutzung / Stand</th></tr></thead><tbody><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/workspace-search" target="_blank" rel="noreferrer">workspace-search</a></td><td>Findet platzierte Blocks im Arbeitsbereich; getrennt von der Toolboxsuche. Seit 0.1.21 verfügbar.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/toolbox-search" target="_blank" rel="noreferrer">toolbox-search</a></td><td>Blocksuche am Menüende, deutsche Suchhinweise; Treffer behalten Dropdowns und Shadows.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-multilineinput" target="_blank" rel="noreferrer">field-multilineinput</a></td><td>Im Textblock; Zeilenumbrüche bleiben im Projekt und YAML erhalten.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-slider" target="_blank" rel="noreferrer">field-slider</a></td><td>Im Prozentblock; 0–100 mit genauer Zahleneingabe.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-colour" target="_blank" rel="noreferrer">field-colour</a></td><td>Im Farbblock; Hex wird für die Lichtaktion nach RGB umgewandelt. Zufall/RGB/Mischung seit 0.1.15 mit eigenen HA-Generatoren.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-dark" target="_blank" rel="noreferrer">theme-dark</a></td><td>Dunkle Arbeitsfläche und Blockauswahl; Teil der gespeicherten Theme-Auswahl.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-modern" target="_blank" rel="noreferrer">theme-modern</a></td><td>Originalpalette mit kräftigeren Rändern; eigene Blocks über Theme-Stile.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/theme-tritanopia" target="_blank" rel="noreferrer">theme-tritanopia</a></td><td>Originalpalette für Standardgruppen, passende UGSo-Erweiterungsfarben und adaptive Schriftkontraste.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/zoom-to-fit" target="_blank" rel="noreferrer">zoom-to-fit</a></td><td>Zusätzlicher Einpassen-Knopf neben den Zoom-Reglern; auch per Tastatur.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-date" target="_blank" rel="noreferrer">field-date</a></td><td>Im Datumsvergleich; UGSo-Unterklasse sichert den verzögerten Kalenderaufruf ab.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-dependent-dropdown" target="_blank" rel="noreferrer">field-dependent-dropdown</a></td><td>Im Helferblock; Helfertyp bestimmt Aktionen. Keine Live-HA-Auswahl.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/block-plus-minus" target="_blank" rel="noreferrer">block-plus-minus</a></td><td>Bedienprinzip in eigenen HA-Blocks umgesetzt; Originalplugin nicht installiert. Zahnrad bleibt verfügbar.</td></tr><tr><td><a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/block-dynamic-connection" target="_blank" rel="noreferrer">block-dynamic-connection</a></td><td>Noch nicht eingebunden. Automatisch wachsende Anschlüsse, Textverknüpfung und Listen sind geplant.</td></tr></tbody></table><p>Die Farbauswahl verwendet zusätzlich die indirekte Abhängigkeit <a href="https://github.com/raspberrypifoundation/blockly-samples/tree/main/plugins/field-grid-dropdown" target="_blank" rel="noreferrer">field-grid-dropdown</a>. HA-Ausgabe wird von uns erzeugt; die mitgelieferten JavaScript-Generatoren werden nicht verwendet.</p><p><a href="/projects/blocks-for-ha/">Zur Übersicht</a></p><p>Benutzerdefinierte Blocks seit 0.1.18 ergänzen die 163 nativen Typen. <a href="./custom-blocks">Editor</a> und <a href="./catalog/">Paketkatalog</a>.</p><h2 id="trigger-ids-und-mehrere-ziele" tabindex="-1">Trigger-IDs und mehrere Ziele <a class="header-anchor" href="#trigger-ids-und-mehrere-ziele" aria-label="Permalink to &quot;Trigger-IDs und mehrere Ziele&quot;">​</a></h2><p>Seit <strong>0.1.28</strong>: Zustandslisten über <strong>Zustände als JSON-Liste</strong>, z. B. <code>[&quot;1_single&quot;,&quot;1_double&quot;]</code>; optionale Trigger-IDs in allen Standardauslösern; <strong>Ausgelöst durch ID</strong> als native Trigger-Bedingung (einzelne ID oder JSON-Liste). Allgemeine HA-Aktionen unterstützen <strong>Ziele als JSON-Liste</strong>, optionale Metadaten und erhalten ausdrücklich leere Datenobjekte. Vierfach-Taster mit vier <code>choose</code>-Zweigen sind vollständig importierbar.</p><p><strong>Einzelne Automation · HA-Editor</strong> gibt keine oberste <code>id</code> aus. Trigger-IDs bleiben erhalten. Projekt und <strong>automations.yaml-Liste</strong> behalten eine vorhandene Automations-ID.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Ausgelöst durch ID</strong><br><code>ugso_trigger_condition</code></td><td><img src="'+lt+'" alt="Ausgelöst durch ID" style="max-width:280px;max-height:180px;"></td><td><code>condition: trigger</code> · <code>id</code></td></tr></tbody></table><p><a href="https://www.home-assistant.io/docs/automation/trigger/#trigger-id" target="_blank" rel="noreferrer">Home Assistant: Trigger IDs</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#trigger-condition" target="_blank" rel="noreferrer">Trigger condition</a></p><h2 id="poolpumpen-ereignisse-und-mehrere-uhrzeiten" tabindex="-1">Poolpumpen, Ereignisse und mehrere Uhrzeiten <a class="header-anchor" href="#poolpumpen-ereignisse-und-mehrere-uhrzeiten" aria-label="Permalink to &quot;Poolpumpen, Ereignisse und mehrere Uhrzeiten&quot;">​</a></h2><p>Seit <strong>0.1.30</strong>: Ein Zeit-Auslöser akzeptiert über <strong>Uhrzeiten als JSON-Liste</strong> mehrere feste Uhrzeiten, z. B. <code>[&quot;10:00:00&quot;,&quot;13:00:00&quot;,&quot;19:00:00&quot;]</code>. <strong>Jede Änderung</strong> im Zustandsauslöser lässt <code>to</code> weg; <strong>Entitäten als JSON-Liste</strong> überwacht mehrere Entitäten. Ohne <code>to</code> reagiert HA auch auf Attributänderungen. Der Ereignis-Auslöser unterstützt z. B. <code>timer.finished</code> und einen optionalen JSON-Datenfilter. Die native Zeitbedingung erhält <code>before</code>/<code>after</code> unverändert; feste Uhrzeiten, nach inklusive und vor exklusiv, auch über Mitternacht. Gleiche Grenzen entsprechen ganztägig. Zeithelfer, Zeit-Templates und Wochentagsfilter bleiben hier noch außerhalb des unterstützten Imports. Die vollständige Poolpumpen-Automation bleibt einschließlich mehrzeiligem Timer-Template und verschachteltem <code>choose</code> erhalten.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Ereignis-Auslöser</strong><br><code>ugso_event_trigger</code></td><td><img src="'+gt+'" alt="Ereignis-Auslöser" style="max-width:280px;max-height:180px;"></td><td><code>trigger: event</code> · <code>event_type</code> · <code>event_data</code></td></tr><tr><td><strong>Native HA-Zeitbedingung</strong><br><code>ugso_native_time_condition</code></td><td><img src="'+ht+'" alt="Native HA-Zeitbedingung" style="max-width:280px;max-height:180px;"></td><td><code>condition: time</code> · <code>before</code> · <code>after</code></td></tr></tbody></table><p><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">Home Assistant: triggers</a> · <a href="https://www.home-assistant.io/docs/scripts/conditions/#time-condition" target="_blank" rel="noreferrer">Time condition</a></p><h2 id="temperatur-geandert" tabindex="-1">Temperatur geändert <a class="header-anchor" href="#temperatur-geandert" aria-label="Permalink to &quot;Temperatur geändert&quot;">​</a></h2><p>Seit <strong>0.1.31</strong> unterstützt der neue Block den nativen Auslöser temperature.changed. Ziel (JSON): entity_id als Text oder Liste. Schwelle (JSON): type any, above, below, between oder outside. any benötigt nur type; above/below benötigen value, between/outside value_min und value_max. Zahlen: number plus unit_of_measurement (°C/°F). Referenzen: entity (sensor, number oder input_number). Optional ist eine Trigger-ID. Seit 0.1.39 sind auch Bereich, Gerät, Etage und Label importierbar. MQTT-Topics, qos/retain/evaluate_payload und mehrzeilige JSON-/Jinja-Payloads bleiben erhalten.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Temperatur geändert</strong><br><code>ugso_temperature_trigger</code></td><td><img src="'+ut+'" alt="Temperatur geändert" style="max-width:280px;max-height:180px;"></td><td>temperature.changed</td></tr></tbody></table><p><a href="https://www.home-assistant.io/triggers/temperature.changed/" target="_blank" rel="noreferrer">Home Assistant: temperature.changed</a></p><h2 id="kalender-und-antwortvariablen" tabindex="-1">Kalender und Antwortvariablen <a class="header-anchor" href="#kalender-und-antwortvariablen" aria-label="Permalink to &quot;Kalender und Antwortvariablen&quot;">​</a></h2><p><strong>0.1.32:</strong> <code>calendar.event_started</code> / <code>calendar.event_ended</code>. Ziel: JSON-Objekt mit <code>entity_id</code> als Text oder Liste. Optionen sind optional: <code>offset</code> mit Tagen, Stunden, Minuten und Sekunden (kombinierbar) oder <code>HH:MM:SS</code>; <code>offset_type</code> ist <code>before</code> oder <code>after</code>. Null-Offset, ausgelassene Optionen und optionale Auslöser-ID bleiben erhalten.</p><p>Das Feld <strong>Antwortvariable (optional)</strong> im Block <strong>HA-Aktion</strong> erzeugt <code>response_variable</code>, zum Beispiel <code>termine</code> für <code>calendar.get_events</code>. Leer lässt das Feld im YAML weg. Die vollständige Feiertage-/Ferien-Automation erhält beide Kalender, den HA-Start, Variablen zeitpunkt/termin_aktiv, mehrzeilige Jinja-Templates, choose/default und queued. Home Assistant verarbeitet die Kalender und Templates.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Kalendertermin beginnt/endet</strong><br><code>ugso_calendar_trigger</code></td><td><img src="'+ct+'" alt="Kalendertermin beginnt/endet" style="max-width:280px;max-height:180px;"></td><td>calendar.event_started / calendar.event_ended</td></tr></tbody></table><p><a href="https://www.home-assistant.io/triggers/calendar.event_started/" target="_blank" rel="noreferrer">Home Assistant: calendar.event_started</a> · <a href="https://www.home-assistant.io/triggers/calendar.event_ended/" target="_blank" rel="noreferrer">calendar.event_ended</a> · <a href="https://www.home-assistant.io/actions/calendar.get_events/" target="_blank" rel="noreferrer">calendar.get_events</a></p><h2 id="numerische-ausloser-mit-haltezeit" tabindex="-1">Numerische Auslöser mit Haltezeit <a class="header-anchor" href="#numerische-ausloser-mit-haltezeit" aria-label="Permalink to &quot;Numerische Auslöser mit Haltezeit&quot;">​</a></h2><p>Seit <strong>0.1.33</strong> unterstützt <strong>Zahl über/unter Grenze</strong> mehrere Entitäten: <strong>Entitäten als JSON-Liste</strong> einschalten und etwa <code>[&quot;sensor.temp_1&quot;,&quot;sensor.temp_2&quot;]</code> eintragen. Ohne Haken bleibt die einzelne Entität aktiv. <strong>Haltezeit (JSON)</strong> mit <strong>verwenden</strong> erzeugt das optionale <code>for</code>: etwa <code>{&quot;hours&quot;:0,&quot;minutes&quot;:1,&quot;seconds&quot;:0}</code>, <code>60</code> oder <code>&quot;00:01:00&quot;</code>. Kombinierte days/hours/minutes/seconds/milliseconds, Nulleinträge und HA-Ausgabetemplates bleiben erhalten. Ein deaktivierter Haken lässt <code>for</code> weg. Weiterhin genau eine feste Zahlen-Grenze (above oder below); Trigger-ID und choose-Zweige bleiben erhalten.</p><p>Home Assistant löst nach dem Grenzübertritt aus, sobald der Wert die gesamte Haltezeit auf dieser Seite der Grenze bleibt. Ein HA-Neustart oder Neuladen der Automationen setzt die laufende Haltezeit zurück. <a href="https://www.home-assistant.io/triggers/numeric_state/" target="_blank" rel="noreferrer">Home Assistant: numeric_state</a>.</p><h2 id="mehrere-variablen-in-einer-aktion" tabindex="-1">Mehrere Variablen in einer Aktion <a class="header-anchor" href="#mehrere-variablen-in-einer-aktion" aria-label="Permalink to &quot;Mehrere Variablen in einer Aktion&quot;">​</a></h2><p>Seit <strong>0.1.34</strong> steht im Menü <strong>Variablen</strong> ein gemeinsamer Block <strong>Variablen setzen (JSON)</strong> bereit. Das JSON-Objekt enthält 1–100 Variablennamen mit Text, HA-Template, Zahl, Boolean oder null. Mehrere Einträge bleiben eine einzige native <code>variables</code>-Aktion, einschließlich ihrer Reihenfolge. Einzelne Zuweisungen verwenden weiterhin den bisherigen Setzen-Block. Seit 0.1.39 sind auch Listen/Objekte und Variablen auf Automationsebene unterstützt; siehe <a href="./advanced">HA erweitert und Jinja</a>. Namen und Templates im JSON müssen dort direkt bearbeitet werden; Umbenennen über den Blockly-Dialog ändert diesen freien JSON-Text nicht. Beim Import werden die Namen auch in Blockly registriert.</p><p>Das Timer-Beispiel erhält h/m, beide überwachten Entitäten, die Bedingung und den restart-Modus. Fehlende conditions werden als leere Liste ergänzt.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Variablen setzen (JSON)</strong><br><code>ugso_variables_action</code></td><td><img src="'+mt+'" alt="Variablen setzen (JSON)" style="max-width:280px;max-height:180px;"></td><td>Variablen mit einzelnen Wertfeldern; Listen und Objekte als JSON, neue Namen über zusätzliche Optionen.</td></tr></tbody></table><p><a href="https://www.home-assistant.io/docs/scripts/#variables" target="_blank" rel="noreferrer">Home Assistant: variables</a></p><h2 id="wartezeit-als-zeittext-oder-template" tabindex="-1">Wartezeit als Zeittext oder Template <a class="header-anchor" href="#wartezeit-als-zeittext-oder-template" aria-label="Permalink to &quot;Wartezeit als Zeittext oder Template&quot;">​</a></h2><p>Seit <strong>0.1.35</strong> importiert Blocks native <code>delay</code>-Zeittexte in den neuen Block unter <strong>Timeouts</strong>. Beispiele: <code>00:00:02</code>, <code>01:30</code> (eine Stunde und 30 Minuten), <code>00:00:00.250</code> oder ein HA-Ausgabetemplate. Der Zeittext bleibt ein Text im YAML und im gespeicherten Projekt. Eine Wartezeit verlängert den aktuellen HA-Lauf; nachfolgende Aktionen folgen danach. Bestehende Sekunden- und Einheiten-Blocks bleiben verfügbar. Diese Erweiterung betrifft <code>delay</code>, nicht den Timeout des Warte-bis-Blocks.</p><p>Das Timer-Reset-Beispiel schaltet zunächst timer_reset aus, wartet zwei Sekunden und schaltet anschließend beide Zielentitäten aus. Die Entitäts-ID input_boolean.timer_runing bleibt genau wie im Original erhalten.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Warte Zeittext / Template</strong><br><code>ugso_delay_text</code></td><td><img src="'+pt+'" alt="Warte Zeittext / Template" style="max-width:280px;max-height:180px;"></td><td>Nativer delay-Zeittext / HA-Template.</td></tr></tbody></table><p><a href="https://www.home-assistant.io/docs/scripts/#wait-for-time-to-pass-delay" target="_blank" rel="noreferrer">Home Assistant: delay</a></p><h2 id="dynamische-ha-aktionsnamen" tabindex="-1">Dynamische HA-Aktionsnamen <a class="header-anchor" href="#dynamische-ha-aktionsnamen" aria-label="Permalink to &quot;Dynamische HA-Aktionsnamen&quot;">​</a></h2><p>Seit <strong>0.1.36</strong> akzeptiert das erste Feld im Block <strong>HA-Aktion</strong> einen statischen Aktionsnamen oder eine Jinja-Vorlage. Das Feld lässt sich mehrzeilig bearbeiten. Beispiele: <code>input_boolean.turn_on</code>, <code>input_boolean.turn_</code> mit angehängtem Jinja-Ausdruck oder ein vollständiges if/else-Template. Ziel, Daten, Metadaten und Antwortvariable bleiben in ihren bisherigen Feldern. Die Vorlage und ihre Zeilenumbrüche bleiben bei Import, Projekt-Speicherung und YAML-Export erhalten.</p><p>Beim Shelly-Beispiel bleibt die zusammengesetzte Aktion <code>input_boolean.turn_</code> plus Zustandsabfrage erhalten, ebenso die verschachtelten choose-Zweige. Home Assistant wertet den Aktionsnamen erst beim Ausführen aus; er muss dann einen vorhandenen Dienstnamen ergeben. Blocks prüft statische Aktionsnamen und vorhandene Template-Klammern, keine Jinja-Syntax oder Laufzeitergebnisse. Zielentitäten müssen weiterhin feste IDs sein; Templates für ganze Datenobjekte sind nicht Teil dieser Erweiterung.</p><p><a href="https://www.home-assistant.io/docs/scripts/perform-actions/#choosing-the-action-with-a-template" target="_blank" rel="noreferrer">Home Assistant: choosing the action with a template</a></p><h2 id="zeitmuster-ausloser" tabindex="-1">Zeitmuster-Auslöser <a class="header-anchor" href="#zeitmuster-ausloser" aria-label="Permalink to &quot;Zeitmuster-Auslöser&quot;">​</a></h2><p>Unter <strong>Auslöser</strong> steht seit <strong>0.1.37</strong> ein nativer <code>time_pattern</code>-Block. Das JSON-Feld enthält beispielsweise <code>{&quot;seconds&quot;:&quot;/30&quot;}</code> für die Sekunden 0 und 30 jeder Minute. Optional sind <code>hours</code>, <code>minutes</code> und <code>seconds</code>; mindestens ein Feld ist erforderlich. Feste Werte: Stunden 0–23, Minuten/Sekunden 0–59, als Zahl oder Text ohne führende Nullen. <code>*</code> passt auf jeden Wert, <code>/n</code> auf durch n teilbare Werte (n &gt; 0 innerhalb des Wertebereichs). Fehlende Einheiten und Zahl/Text-Typen bleiben unverändert; Home Assistant ergänzt seine Standardwerte zur Laufzeit. Optional ist eine Auslöser-ID.</p><p>Die LCD-Automation mit vier <code>input_text.set_value</code>-Aktionen und <code>mode: restart</code> wurde vollständig geprüft: Jinja, Formatierung, Textkürzung, Auffüllen und Zeilenumbrüche bleiben erhalten. Home Assistant führt die Templates und den Zeitplan aus.</p><table tabindex="0"><thead><tr><th>Block</th><th>Type</th></tr></thead><tbody><tr><td><img src="'+bt+'" alt="Zeitmuster (JSON)"></td><td><code>ugso_time_pattern_trigger</code></td></tr></tbody></table><p><a href="https://www.home-assistant.io/triggers/time_pattern/" target="_blank" rel="noreferrer">Home Assistant: time_pattern</a>.</p><h2 id="dynamische-zielentitaten" tabindex="-1">Dynamische Zielentitäten <a class="header-anchor" href="#dynamische-zielentitaten" aria-label="Permalink to &quot;Dynamische Zielentitäten&quot;">​</a></h2><p>Seit <strong>0.1.39</strong> akzeptiert das Feld <strong>Ziel</strong> in der allgemeinen <strong>HA-Aktion</strong> eine feste Entitäts-ID oder ein HA-Template, zum Beispiel <code>{{ ziel_tv }}</code>. Der Entitätsdialog bietet dafür ein mehrzeiliges Eingabefeld. Auch die JSON-Zielliste darf feste IDs und Templates enthalten. Jinja bleibt unverändert erhalten und wird erst von Home Assistant ausgewertet. Dynamische Ziele werden beim Import in der allgemeinen HA-Aktion dargestellt; spezialisierte Schaltblöcke würden die Domain nicht zuverlässig bestimmen können.</p><p>Die Schlafzimmer-TV-Automation mit einer mehrzeiligen Sommerbetrieb-Variable, 21:30 und 00:30 Uhr und zwei choose-Zweigen ist geprüft. Zielvorlagen, Variableninhalt und Uhrzeitbedingungen bleiben beim Import, Projekt-Neuladen und Export erhalten. Auslöser- und Bedingungsfelder für Entitäts-IDs verlangen weiterhin feste IDs.</p><p><a href="https://www.home-assistant.io/docs/scripts/perform-actions/#setting-targets-and-options-with-a-template" target="_blank" rel="noreferrer">Home Assistant: templates in action targets</a>.</p><h2 id="ha-erweitert-und-jinja-seit-0-1-39" tabindex="-1">HA erweitert und Jinja seit 0.1.39 <a class="header-anchor" href="#ha-erweitert-und-jinja-seit-0-1-39" aria-label="Permalink to &quot;HA erweitert und Jinja seit 0.1.39&quot;">​</a></h2><p><a href="./advanced">Anleitung / Guide</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>HA state</strong><br><code>ugso_ha_state_trigger</code></td><td><img src="'+xt+'" alt="HA state" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA numeric_state</strong><br><code>ugso_ha_numeric_state_trigger</code></td><td><img src="'+lr+'" alt="HA numeric_state" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA time</strong><br><code>ugso_ha_time_trigger</code></td><td><img src="'+_t+'" alt="HA time" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA sun</strong><br><code>ugso_ha_sun_trigger</code></td><td><img src="'+ft+'" alt="HA sun" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA homeassistant</strong><br><code>ugso_ha_homeassistant_trigger</code></td><td><img src="'+kt+'" alt="HA homeassistant" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA mqtt</strong><br><code>ugso_ha_mqtt_trigger</code></td><td><img src="'+wt+'" alt="HA mqtt" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA template</strong><br><code>ugso_ha_template_trigger</code></td><td><img src="'+At+'" alt="HA template" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA webhook</strong><br><code>ugso_ha_webhook_trigger</code></td><td><img src="'+zt+'" alt="HA webhook" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA zone</strong><br><code>ugso_ha_zone_trigger</code></td><td><img src="'+yt+'" alt="HA zone" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA device</strong><br><code>ugso_ha_device_trigger</code></td><td><img src="'+vt+'" alt="HA device" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA tag</strong><br><code>ugso_ha_tag_trigger</code></td><td><img src="'+Bt+'" alt="HA tag" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA conversation</strong><br><code>ugso_ha_conversation_trigger</code></td><td><img src="'+St+'" alt="HA conversation" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA geo_location</strong><br><code>ugso_ha_geo_location_trigger</code></td><td><img src="'+Tt+'" alt="HA geo_location" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA calendar</strong><br><code>ugso_ha_calendar_trigger</code></td><td><img src="'+Ht+'" alt="HA calendar" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA event</strong><br><code>ugso_ha_event_trigger</code></td><td><img src="'+Et+'" alt="HA event" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA-Auslöser (erweitert)</strong><br><code>ugso_ha_trigger</code></td><td><img src="'+Zt+'" alt="HA-Auslöser (erweitert)" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA-Bedingung (erweitert)</strong><br><code>ugso_ha_condition</code></td><td><img src="'+jt+'" alt="HA-Bedingung (erweitert)" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA-Schritt (erweitert)</strong><br><code>ugso_ha_action</code></td><td><img src="'+gr+'" alt="HA-Schritt (erweitert)" style="max-width:280px;max-height:180px;"></td><td>Beschriftete HA-Eingaben und zusätzliche JSON-Optionen. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA-Aktion Zielart Ziel Daten Schrittoptionen</strong><br><code>ugso_target_action</code></td><td><img src="'+Dt+'" alt="HA-Aktion Zielart Ziel Daten Schrittoptionen" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>HA-Integration Ziel Optionen verwenden</strong><br><code>ugso_integration_trigger</code></td><td><img src="'+Ot+'" alt="HA-Integration Ziel Optionen verwenden" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Aktionsgruppe</strong><br><code>ugso_sequence</code></td><td><img src="'+Lt+'" alt="Aktionsgruppe" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Parallel Zweig 1 Zweig 2</strong><br><code>ugso_parallel</code></td><td><img src="'+Nt+'" alt="Parallel Zweig 1 Zweig 2" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Warte auf Auslöser Optionen</strong><br><code>ugso_wait_trigger</code></td><td><img src="'+Jt+'" alt="Warte auf Auslöser Optionen" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Nur weiter wenn</strong><br><code>ugso_condition_step</code></td><td><img src="'+Ft+'" alt="Nur weiter wenn" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Ereignis auslösen Daten</strong><br><code>ugso_fire_event</code></td><td><img src="'+Wt+'" alt="Ereignis auslösen Daten" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Assist antwortet</strong><br><code>ugso_assist_response</code></td><td><img src="'+It+'" alt="Assist antwortet" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Szene aktivieren</strong><br><code>ugso_scene</code></td><td><img src="'+Vt+'" alt="Szene aktivieren" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Jinja (experimentell)</strong><br><code>ugso_jinja_value</code></td><td><img src="'+qt+'" alt="Jinja (experimentell)" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr><tr><td><strong>Jinja-Bedingung (experimentell)</strong><br><code>ugso_jinja_condition</code></td><td><img src="'+Ut+'" alt="Jinja-Bedingung (experimentell)" style="max-width:280px;max-height:180px;"></td><td>Erweiterte HA-Felder oder Original-Jinja. Unterstützte Struktur wird geprüft; Integration und Ausführung in HA prüfen.</td></tr></tbody></table><h2 id="jinja-strukturen-experimentell" tabindex="-1">Jinja-Strukturen (experimentell) <a class="header-anchor" href="#jinja-strukturen-experimentell" aria-label="Permalink to &quot;Jinja-Strukturen (experimentell)&quot;">​</a></h2><p>Seit <strong>0.1.64</strong> stehen die Freicode-Blöcke nur unter <strong>Templates</strong> als <strong>Jinja – eigener Code</strong> und <strong>Jinja – eigene Bedingung</strong>. Die älteren Typen <code>ugso_jinja_value</code> und <code>ugso_jinja_condition</code> bleiben für gespeicherte Projekte und den Import lesbar; die folgenden Bilder dokumentieren diese alten Typen. <a href="./system-template">Zweckbezogene Templates</a>.</p><p>15 neue Typen seit 0.1.41. Die äußeren Wert-/Bedingungsblocks verbinden die verschachtelten Teile mit HA. Jinja-Ausdrücke und Template-Teile haben eigene typisierte Anschlüsse. <a href="./advanced#jinja-experimentell">Einlesen, Bearbeiten und Grenzen</a>.</p><table tabindex="0"><thead><tr><th>Block</th><th>Bild</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Jinja zusammengesetzt</strong><br><code>ugso_jinja_composed_value</code></td><td><img src="'+hr+'" alt="Jinja zusammengesetzt" style="max-width:280px;max-height:180px;"></td><td>Äußerer Wertblock: zusammenhängendes Template; Original bleibt bis zur Bearbeitung erhalten.</td></tr><tr><td><strong>Jinja-Bedingung zusammengesetzt</strong><br><code>ugso_jinja_composed_condition</code></td><td><img src="'+Mt+'" alt="Jinja-Bedingung zusammengesetzt" style="max-width:280px;max-height:180px;"></td><td>Äußerer Boolean-Block für eine HA-Template-Bedingung.</td></tr><tr><td><strong>Entität Funktion</strong><br><code>ugso_jinja_entity</code></td><td><img src="'+Pt+'" alt="Entität Funktion" style="max-width:280px;max-height:180px;"></td><td>Entität suchen und states/state_attr/is_state/is_state_attr wählen; zusätzliche Argumente anschließen.</td></tr><tr><td><strong>Filter Argumente Wert</strong><br><code>ugso_jinja_filter</code></td><td><img src="'+Gt+'" alt="Filter Argumente Wert" style="max-width:280px;max-height:180px;"></td><td>Filter auswählen; 0–3 Positionsargumente und einen Jinja-Ausdruck anschließen.</td></tr><tr><td><strong>Literal (Jinja)</strong><br><code>ugso_jinja_literal</code></td><td><img src="'+Kt+'" alt="Literal (Jinja)" style="max-width:280px;max-height:180px;"></td><td>Zahl, String in Anführungszeichen, true/false oder none in Jinja-Schreibweise.</td></tr><tr><td><strong>Jinja-Variable</strong><br><code>ugso_jinja_variable</code></td><td><img src="'+Rt+'" alt="Jinja-Variable" style="max-width:280px;max-height:180px;"></td><td>Einfacher Jinja-Variablenname als Text; keine automatische Blockly-Umbenennung.</td></tr><tr><td><strong>Jetzt (Jinja)</strong><br><code>ugso_jinja_now</code></td><td><img src="'+Ct+'" alt="Jetzt (Jinja)" style="max-width:280px;max-height:180px;"></td><td>now() erzeugen; Home Assistant liefert den Zeitpunkt bei der Auswertung.</td></tr><tr><td><strong>Ausdruck</strong><br><code>ugso_jinja_binary</code></td><td><img src="'+Yt+'" alt="Ausdruck" style="max-width:280px;max-height:180px;"></td><td>Zwei Jinja-Ausdrücke berechnen, vergleichen oder mit and/or verbinden.</td></tr><tr><td><strong>Ausdruck</strong><br><code>ugso_jinja_unary</code></td><td><img src="'+Qt+'" alt="Ausdruck" style="max-width:280px;max-height:180px;"></td><td>not, negatives oder positives Vorzeichen für einen Jinja-Ausdruck.</td></tr><tr><td><strong>Wert wenn sonst</strong><br><code>ugso_jinja_select</code></td><td><img src="'+$t+'" alt="Wert wenn sonst" style="max-width:280px;max-height:180px;"></td><td>Wert wählen: yes if test else no. Alle drei Ausdruckseingänge sind erforderlich.</td></tr><tr><td><strong>Ausgeben</strong><br><code>ugso_jinja_output</code></td><td><img src="'+Xt+'" alt="Ausgeben" style="max-width:280px;max-height:180px;"></td><td>Einen Ausdruck als <code>{{ ... }}</code> innerhalb eines Templates ausgeben.</td></tr><tr><td><strong>Jinja-Text</strong><br><code>ugso_jinja_text</code></td><td><img src="'+er+'" alt="Jinja-Text" style="max-width:280px;max-height:180px;"></td><td>Wörtlicher Text einschließlich Leerraum; Jinja-Steuerzeichen hier nicht einfügen.</td></tr><tr><td><strong>Template-Teile danach</strong><br><code>ugso_jinja_join</code></td><td><img src="'+tr+'" alt="Template-Teile danach" style="max-width:280px;max-height:180px;"></td><td>Zwei Template-Teile in der dargestellten Reihenfolge verbinden.</td></tr><tr><td><strong>Wenn Text sonst</strong><br><code>ugso_jinja_if</code></td><td><img src="'+rr+'" alt="Wenn Text sonst" style="max-width:280px;max-height:180px;"></td><td>if/else mit Bedingung und verschachtelten Text-/Ausgabeteilen.</td></tr><tr><td><strong>Für in Text wenn leer</strong><br><code>ugso_jinja_for</code></td><td><img src="'+nr+'" alt="Für in Text wenn leer" style="max-width:280px;max-height:180px;"></td><td>Einfache for-Schleife: Variable, Ausdruck, Template-Inhalt und optionaler Leerfall.</td></tr></tbody></table>',114)])])}const Zr=ur(br,[["render",xr]]);export{Er as __pageData,Zr as default};
